use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,process::Command,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/direct-ref-pack";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let receipts:Value=serde_json::from_slice(&fs::read(format!("{R}/probe-artifacts.json")).unwrap()).unwrap();let mut record=BTreeMap::new();for label in["frozen","fresh"]{
    let path=format!("{R}/{label}-probe");let changed=hash(&path);let expected=receipts[label]["sha256"].as_str().unwrap();assert_ne!(changed,expected);
    let preserved=format!("{R}/{label}-probe.objcopy-mutated");assert!(!std::path::Path::new(&preserved).exists());fs::rename(&path,&preserved).unwrap();
    let cmd:Value=serde_json::from_slice(&fs::read(format!("{R}/link-{label}-command.json")).unwrap()).unwrap();let args:Vec<String>=serde_json::from_value(cmd["argv"].clone()).unwrap();
    let out=Command::new("rustc").args(&args).current_dir("/home/ubuntu/src/zk-tools").output().unwrap();fs::write(format!("{R}/restore-{label}-stdout.log"),out.stdout).unwrap();fs::write(format!("{R}/restore-{label}-stderr.log"),out.stderr).unwrap();assert!(out.status.success());let recovered=hash(&path);assert_eq!(recovered,expected,"exact original hash required for {label}");
    record.insert(label,json!({"pre_capture_sha256":expected,"post_objcopy_sha256":changed,"post_objcopy_copy":preserved,"restored_sha256":recovered,"restoration":"identical recorded rustc probe link command, source and frozen libraries; same output path/cwd; exact pre-capture hash recovered","Cargo_build_repeated":false,"probe_link_repeated_only_after_all_capture":true}));
}fs::write(format!("{R}/control-restoration.json"),serde_json::to_vec_pretty(&json!({"scope":"post-capture diagnostic tool rewrite recovery only","cause":"GNU objcopy --dump-section INPUT with omitted OUTPUT rewrites INPUT; original captures already completed and all source/binary pins had passed","variants":record,"kernel_changed":false,"all_timings_tests_profiles_repeated":false,"selected_probe_untouched":true,"future_rule":"read ELF sections directly, or use distinct objcopy OUTPUT; never objcopy original evidence executable in place"})).unwrap()).unwrap();println!("Restored bothOFFexecutables EXACT pre-capture hashes; noCargo/test/timing/profile repeats");}
